import users from './users.json' with {type: 'json'};

export async function listTools() {
  return [
    {
      name: 'users_get_many',
      description: 'Look up multiple users by ID. Returns one line per requested ID.',
      inputSchema: {
        type: 'object',
        properties: {
          user_ids: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
            maxItems: 5,
            uniqueItems: true
          }
        },
        required: ['user_ids'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'users_get_many') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate args is an object
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }

  // Check for extra fields
  const allowedFields = ['user_ids'];
  for (const key of Object.keys(args)) {
    if (!allowedFields.includes(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  // Check user_ids exists
  if (!('user_ids' in args)) {
    throw new Error('Missing required field: user_ids');
  }

  const { user_ids } = args;

  // Validate user_ids is an array
  if (!Array.isArray(user_ids)) {
    throw new Error('user_ids must be an array');
  }

  // Non-empty
  if (user_ids.length === 0) {
    throw new Error('user_ids must not be empty');
  }

  // At most 5
  if (user_ids.length > 5) {
    throw new Error('user_ids must have at most 5 entries');
  }

  // All entries must be strings
  for (const id of user_ids) {
    if (typeof id !== 'string') {
      throw new Error('All user_ids must be strings');
    }
  }

  // No duplicates
  const seen = new Set();
  for (const id of user_ids) {
    if (seen.has(id)) {
      throw new Error('Duplicate user_ids are not allowed');
    }
    seen.add(id);
  }

  // Build result - one line per id
  const lines = [];
  for (const id of user_ids) {
    if (id in users) {
      lines.push(`${id}: ${users[id].name}`);
    } else {
      lines.push(`${id}: missing`);
    }
  }

  return {
    content: [{ type: 'text', text: lines.join('\n') }]
  };
}
